#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0,
    /* 当前列只能来自上一行同列或左列，必须从右向左更新以保留旧状态。 */
    best = 0, i = 0, j = 0, n = 0;
    n = read();
    for (i = 0; i < n; i += 1)  {
        for (j = 0; j < (i + 1); j += 1)  {
            b[j] = read();
        }
        for (j = i; j > (-1); j += -1)  {
            best = 0;
            if (j < i)  {
                best = a[j];
            }
            if (j > 0)  {
                best = mx(best, a[(j - 1)]);
            }
            a[j] = (best + b[j]);
        }
    }
    ans = 0;
    for (j = 0; j < n; j += 1)  {
        ans = mx(ans, a[j]);
    }
    /* 扫描最后一行的所有最大路径和，终点不限于最左或最右格。 */
    emit(ans);
    return 0;
}

