    let mut best: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut n: i32 = 0;
    n = reader.read();
    i = 0;
    while i < n  {
        j = 0;
        while j < (i + 1)  {
            b[(j) as usize] = reader.read();
            j += 1;
        }
        j = i;
        while j > (-1)  {
            /* 当前列只能来自上一行同列或左列，必须从右向左更新以保留旧状态。 */
            best = 0;
            if (j < i)  {
                best = a[(j) as usize];
            }
            if (j > 0)  {
                best = mx(best, a[(j - 1) as usize]);
            }
            a[(j) as usize] = (best + b[(j) as usize]);
            j += -1;
        }
        i += 1;
    }
